import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/* eslint-disable */
import { format_Date } from "@/JsonFiles/DateFormate.js";
import SnackBar from "@/components/SnackBar.vue";
import ViewForm from "@/components/UserLevelForms/ViewForm.vue";
import { list_workflow } from "@/graphql/queries.js";
import { getData } from "@/mixins/AllQueries.js";
import CreateTicketDialog from "../Tickets/CreateTicketDialog.vue";
import html2canvas from "html2canvas";
export default {
  components: {
    ViewForm,
    SnackBar,
    CreateTicketDialog
  },
  mixins: [getData],
  data() {
    return {
      searchlist: "",
      headers: [{
        title: "Name",
        key: "workflow_name",
        sortable: false
      }, {
        title: "Description",
        key: "workflow_description",
        sortable: false
      }, {
        title: "Created On",
        key: "workflow_created_on",
        sortable: false
      }, {
        title: "Speed",
        key: "workflow_speed",
        sortable: false
      }],
      tableData: [],
      tableLoading: false,
      formInfo: {},
      formDialog: false,
      componentCheck: 0,
      formActionType: "initiate",
      SnackBarComponent: {},
      isVisible: false,
      // Pagination properties
      currentPage: 1,
      itemsPerPage: 20,
      totalItems: 0,
      windowHeight: 0,
      //Screenshot Values
      DialogCreateTicket: false,
      ScreenshotFile: null,
      orgDetails: {
        bucket_name: "stichh-medias",
        region: "us-east-1"
      }
    };
  },
  computed: {
    modernHeaders() {
      return [{
        title: "Name",
        key: "workflow_name",
        sortable: false
      }, {
        title: "Description",
        key: "workflow_description",
        sortable: false
      }, {
        title: "Created On",
        key: "workflow_created_on",
        sortable: false
      }, {
        title: "Speed",
        key: "workflow_speed",
        sortable: false
      }];
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    currentPage(newVal, oldVal) {
      // When the page changes, scroll to top of table
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    },
    searchlist() {
      // Reset to first page when searching
      this.currentPage = 1;
    }
  },
  created() {
    this.windowHeight = window.innerHeight - 220;
    this.isVisible = true;
    this.get_all_flows();
  },
  methods: {
    refresh_list() {
      this.next_token = null;
      this.get_all_flows();
    },
    async TakeScreenshot() {
      const target = document.body;
      const canvas = await html2canvas(target, {
        scale: window.devicePixelRatio || 2,
        useCORS: true,
        logging: false,
        windowWidth: document.documentElement.scrollWidth,
        windowHeight: document.documentElement.scrollHeight
      });
      const dataUrl = canvas.toDataURL("image/png");
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], "screenshot.png", {
        type: "image/png"
      });
      this.ScreenshotFile = file;
      this.DialogCreateTicket = true;
    },
    DialogCreateTicketEmit() {
      this.DialogCreateTicket = false;
    },
    back_call() {
      this.$router.push("/home/DashboardView");
    },
    async get_all_flows() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      const variables = {
        organization_id: data.organization.organization_id,
        limit: 1000,
        nextToken: null,
        user_id: data.user.user_id
      };
      this.tableData = [];
      this.fetchData(list_workflow, variables).then(() => {
        var response = JSON.parse(this.queryResponse.data.list_workflow);
        this.tableLoading = false;
        this.tableData = response.details;
        this.tableData = this.tableData.filter(obj => (obj.workflow_design_type === "DEFAULT" || obj.workflow_design_type === undefined) && obj.workflow_deploy_status === "DEPLOY");

        // Update total items for pagination
        this.totalItems = this.tableData.length;
        localStorage.setItem("workflowList", JSON.stringify(response.details));
      }).catch(error => {
        this.tableLoading = false;
        console.error("Error fetching data:", error);
      });
    },
    fetch_value(val) {
      return format_Date(val);
    },
    handle_row_click(click, value) {
      this.formInfo = value.item;
      this.componentCheck = 1;
      this.formDialog = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.formDialog = false;
    },
    validate_message(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
  }
};
